-- Test verisi oluştur
CREATE TABLE IF NOT EXISTS musteriler (id INTEGER PRIMARY KEY, ad TEXT NOT NULL, sehir TEXT NOT NULL, kayit_tarihi TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS urunler (id INTEGER PRIMARY KEY, ad TEXT NOT NULL, kategori TEXT NOT NULL, fiyat REAL NOT NULL);
CREATE TABLE IF NOT EXISTS siparisler (id INTEGER PRIMARY KEY, musteri_id INTEGER NOT NULL, tarih TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS siparis_kalemleri (siparis_id INTEGER NOT NULL, urun_id INTEGER NOT NULL, adet INTEGER NOT NULL, birim_fiyat REAL NOT NULL);
CREATE TABLE IF NOT EXISTS iadeler (id INTEGER PRIMARY KEY, siparis_id INTEGER NOT NULL, urun_id INTEGER NOT NULL, adet INTEGER NOT NULL);

-- Test verisi ekle
INSERT INTO musteriler (id, ad, sehir, kayit_tarihi) VALUES (1, 'Ahmet', 'Ankara', '2024-01-01');
INSERT INTO musteriler (id, ad, sehir, kayit_tarihi) VALUES (2, 'Mehmet', 'Istanbul', '2024-01-01');

-- 2024-11, 2024-12, 2025-01 üç aylık seri için siparişler (Ahmet için)
INSERT INTO siparisler (id, musteri_id, tarih) VALUES (1, 1, '2024-11-01');
INSERT INTO siparisler (id, musteri_id, tarih) VALUES (2, 1, '2024-12-01');
INSERT INTO siparisler (id, musteri_id, tarih) VALUES (3, 1, '2025-01-01');

-- 2024-10, 2024-11, 2024-12 üç aylık seri için siparişler (Mehmet için)
INSERT INTO siparisler (id, musteri_id, tarih) VALUES (4, 2, '2024-10-01');
INSERT INTO siparisler (id, musteri_id, tarih) VALUES (5, 2, '2024-11-01');
INSERT INTO siparisler (id, musteri_id, tarih) VALUES (6, 2, '2024-12-01');

-- Ahmet için daha uzun bir seri: 2024-10, 2024-11, 2024-12, 2025-01 (4 ay)
INSERT INTO siparisler (id, musteri_id, tarih) VALUES (7, 1, '2024-10-15');
INSERT INTO siparisler (id, musteri_id, tarih) VALUES (8, 1, '2025-01-15');

-- Mehmet için sadece 2 aylik seri (2025-01, 2025-02)
INSERT INTO siparisler (id, musteri_id, tarih) VALUES (9, 2, '2025-01-01');
INSERT INTO siparisler (id, musteri_id, tarih) VALUES (10, 2, '2025-02-01');

WITH
siparis_aylari AS (
    SELECT DISTINCT 
        m.id AS musteri_id,
        m.ad AS musteri_ad,
        s.tarih AS ay,
        ROW_NUMBER() OVER (PARTITION BY m.id ORDER BY s.tarih) AS rn
    FROM siparisler s
    JOIN musteriler m ON s.musteri_id = m.id
    WHERE s.tarih LIKE '____-__'
),
ardisik_sayim AS (
    SELECT 
        musteri_id,
        musteri_ad,
        ay,
        rn,
        rn - CAST(STRFTIME('%j', ay) AS INTEGER) AS grup_id,
        COUNT(*) OVER (PARTITION BY musteri_id, rn - CAST(STRFTIME('%j', ay) AS INTEGER)) AS seriuzunluk
    FROM siparis_aylari
),
grup_maxlari AS (
    SELECT 
        musteri_id,
        musteri_ad,
        rn - CAST(STRFTIME('%j', ay) AS INTEGER) AS grup_id,
        MAX(seriuzunluk) AS max_uzunluk,
        MIN(ay) AS basin_ay
    FROM ardisik_sayim
    GROUP BY musteri_id, rn - CAST(STRFTIME('%j', ay) AS INTEGER)
),
enuzunguplus AS (
    SELECT musteri_id, MAX(max_uzunluk) AS en_uzun_seri
    FROM grup_maxlari
    GROUP BY musteri_id
),
sonuc AS (
    SELECT 
        g.musteri_id,
        g.musteri_ad,
        g.max_uzunluk,
        g.basin_ay,
        ROW_NUMBER() OVER (PARTITION BY g.musteri_id ORDER BY g.max_uzunluk DESC, g.musteri_ad ASC) AS sort_rank
    FROM grup_maxlari g
    JOIN enuzunguplus e ON g.musteri_id = e.musteri_id
    WHERE g.max_uzunluk = e.en_uzun_seri AND g.max_uzunluk >= 3
)
SELECT musteri_ad, max_uzunluk AS ay, basin_ay
FROM sonuc
WHERE sort_rank = 1
ORDER BY ay DESC, musteri_ad ASC;

